// Extract the <script> body and run it against a mock DOM + localStorage.
const src = require('fs').readFileSync('index.html','utf8')
  .match(/<script>([\s\S]*?)<\/script>/)[1];

function makeEnv(initialStorage) {
  const store = { ...initialStorage };
  const note = { value: '', listeners: {} };
  const clear = { listeners: {} };
  const localStorage = {
    getItem: k => (k in store ? store[k] : null),
    setItem: (k, v) => { store[k] = String(v); },
  };
  const document = {
    getElementById: id => (id === 'note' ? note : clear),
  };
  const listeners = [];
  const addEventListener = (el, ev, fn) => listeners.push([el, ev, fn]);
  // patch addEventListener onto mock elements
  note.addEventListener = (ev, fn) => listeners.push([note, ev, fn]);
  clear.addEventListener = (ev, fn) => listeners.push([clear, ev, fn]);
  new Function('document','localStorage', src)(document, localStorage);
  // attach registered listeners
  for (const [el, ev, fn] of listeners) el.listeners[ev] = fn;
  return { store, note, clear, localStorage };
}

// 1) Fresh browser: no stored value -> empty note
let env = makeEnv({});
console.log('fresh load note.value =', JSON.stringify(env.note.value), '(expect "")');

// 2) Type multiline text -> saved on input
env.note.value = 'line one\nline two';
env.note.listeners.input();
console.log('after input, stored =', JSON.stringify(env.store['note-text']));

// 3) Reload in same browser: value restored
env = makeEnv(env.store);
console.log('after reload note.value =', JSON.stringify(env.note.value), '(expect "line one\\nline two")');

// 4) Clear -> empty, and stored as empty string
env.note.listeners.click();
console.log('after clear note.value =', JSON.stringify(env.note.value), 'stored =', JSON.stringify(env.store['note-text']));

// 5) Reload after clear: stays empty
env = makeEnv(env.store);
console.log('after reload-after-clear note.value =', JSON.stringify(env.note.value), '(expect "")');

// 6) Different browser (fresh store of another env) starts empty
env = makeEnv({});
console.log('different browser note.value =', JSON.stringify(env.note.value), '(expect "")');
EOF

